struct ChainLayer { state: Arc<Mutex<ChainState>>, sink: Arc<Mutex<File>> }
impl<S: Subscriber> Layer<S> for ChainLayer {
    fn on_event(&self, event: &Event<'_>, _ctx: Context<'_, S>) {
        let body = canonicalise(event);                 // structured fields, stable order
        let mut s = self.state.lock().unwrap();
        let mut mac = Hmac::<Sha256>::new_from_slice(&s.key).expect("key length");
        mac.update(&s.prev); mac.update(&s.seq.to_be_bytes()); mac.update(&body);
        s.prev = mac.finalize().into_bytes().into(); s.seq += 1;
        self.sink.lock().unwrap().write_all(&body).expect("audit sink");   // O_APPEND
    }
}
